<script setup lang="ts">
import type { GraphMergePreview, GraphNode } from '../graphTypes'
defineProps<{ selected: GraphNode[]; choices: GraphNode[]; query: string; canonicalName: string; preview: GraphMergePreview | null; step: number; blocked: boolean; busy: boolean; valid: boolean; replacing: boolean }>()
const emit = defineEmits<{ 'update:query': [value: string]; 'update:canonicalName': [value: string]; 'update:step': [value: number]; choose: [node: GraphNode]; remove: [node: GraphNode]; preview: []; merge: []; cancel: [] }>()
const types: Record<string, string> = { person: '人物', place: '地点', organization: '组织', item: '物品', skill: '功法', concept: '专有概念' }
</script>
<template>
  <section class="graph-merge-form" aria-label="合并实体表单">
    <div class="merge-flow-heading"><div><h2>{{ replacing ? '重新指定人工合并' : '合并实体' }}</h2><p>把同一个人物或事物的不同名称，整理为一个身份。</p></div><button class="text-button" :disabled="busy" @click="emit('cancel')">取消合并</button></div>
    <ol class="merge-steps" aria-label="合并进度"><li v-for="(label, index) in ['选择实体', '确定名称', '预览确认']" :key="label" :class="{ active: step === index + 1, done: step > index + 1 }" :aria-current="step === index + 1 ? 'step' : undefined"><span>{{ index + 1 }}</span>{{ label }}</li></ol>
    <div v-show="step === 1" class="merge-selection-grid">
      <div class="merge-search-panel"><label class="field"><span>搜索要合并的实体</span><input :value="query" :disabled="blocked" placeholder="输入名称或别名…" @input="emit('update:query', ($event.target as HTMLInputElement).value)" /></label><p class="muted-caption">{{ selected.length ? `仅显示${types[selected[0]!.type] || selected[0]!.type}类型，可继续搜索添加` : '先搜索并选择第一个实体，随后限定同类型' }}</p>
        <ul class="graph-candidates"><li v-for="node in choices" :key="node.id"><button type="button" :disabled="blocked" @click="emit('choose', node)"><span class="entity-avatar">{{ node.name.slice(0, 1) }}</span><span><strong>{{ node.name }}</strong><small>{{ types[node.type] || node.type }} · {{ node.first_mention?.section_title || node.first_mention?.section_id || '全书实体' }}</small><small v-if="node.aliases.length">其他名称：{{ node.aliases.join('、') }}</small></span><span class="candidate-add">＋</span></button></li></ul>
        <div v-if="!choices.length" class="compact-empty"><p>{{ query.trim() ? '没有更多匹配的实体，试试其他名称。' : '从一个名字开始' }}</p></div>
      </div>
      <div class="merge-selected-panel"><div class="pane-heading"><h3>已选实体</h3><span class="count-chip">{{ selected.length }}</span></div><p class="muted-caption">至少选择两个同类型实体</p><ul class="graph-merge-selected"><li v-for="node in selected" :key="node.id"><div><strong>{{ node.name }}</strong><small>{{ types[node.type] || node.type }}</small><div class="tags"><span v-for="alias in node.aliases" :key="alias">{{ alias }}</span></div></div><button class="icon-button" :aria-label="`移除 ${node.name}`" :disabled="blocked" @click="emit('remove', node)">×</button></li></ul><div v-if="!selected.length" class="compact-empty">从候选中添加实体，在这里进行对比</div></div>
    </div>
    <div v-show="step === 2" class="merge-name-stage"><div class="merge-name-source"><span class="section-kicker">已选择 {{ selected.length }} 个实体</span><div class="name-cloud"><span v-for="node in selected" :key="node.id">{{ node.name }}</span></div><p class="muted-caption">名称、原文提及和关系将一起更新；合并作用于全书，不受章节筛选限制。</p></div><div class="merge-name-target"><span class="section-kicker">最终保留的身份</span><label class="field"><span>合并后的实体名称</span><input :value="canonicalName" maxlength="100" :disabled="blocked" placeholder="直接输入最终保留的名称" @input="emit('update:canonicalName', ($event.target as HTMLInputElement).value)" /></label><p class="muted-caption">其他名称将作为别名保留。下一步可检查影响范围。</p></div></div>
    <div v-if="step === 3 && preview" class="graph-merge-preview" role="status"><div class="merge-comparison"><div><span class="section-kicker">合并来源</span><article v-for="entity in preview.entities" :key="entity.id"><strong>{{ entity.name }}</strong><span>{{ entity.mention_count }} 处提及</span></article></div><span class="comparison-arrow">→</span><div class="merge-target-card"><span class="section-kicker">合并后的实体</span><h3>{{ preview.target.name }}</h3><p>{{ preview.target.mention_count }} 处原文提及</p><div class="tags"><span v-for="alias in preview.target.aliases" :key="alias">{{ alias }}</span></div></div></div><dl class="merge-impact"><div><dt>全图关系变化</dt><dd>{{ preview.relation_count_before }} <span>→</span> {{ preview.relation_count_after }}</dd></div><div><dt>移除自关联</dt><dd>{{ preview.self_relations_removed }} <small>条</small></dd></div><div><dt>原始事实记录</dt><dd>完整保留</dd></div></dl><p class="muted-caption">保存后生成新版本，可在修改历史中恢复之前的图谱。</p></div>
    <footer class="flow-actions"><span>步骤 {{ step }} / 3</span><button v-if="step > 1" class="button secondary" :disabled="busy" @click="emit('update:step', step - 1)">上一步</button><button v-if="step === 1" class="button primary" :disabled="blocked || selected.length < 2" @click="emit('update:step', 2)">确定名称 →</button><button v-if="step === 2" class="button primary" :disabled="blocked || !valid" @click="emit('preview')">{{ busy ? '正在生成预览…' : '预览合并' }}</button><button v-if="step === 3" class="button primary" :disabled="blocked || !valid || !preview" @click="emit('merge')">{{ busy ? '保存中…' : '确认合并并保存版本' }}</button></footer>
  </section>
</template>
